grid = [[5,6,6,6,6,6],[5,6,6,6,6,6],[5,6,6,6,6,6],[5,6,6,6,6,6],
        [6,6,6,6,6,6],[6,6,6,6,6,6],[6,2,6,6,6,5],[6,6,2,6,6,5],[6,2,6,6,6,5],[6,2,6,6,6,5]]
out = [row[:] for row in grid]
# mirrored full lines on left bar offsets 0-3 (rows 0-3), spanning cols1-4
for r in range(4):
    for c in range(1,5):
        out[r][c] = 2
# through-seed lines: row6 seed c1; row7 seed c2; row8 seed c1; row9 seed c1
seeds = {6:1, 7:2, 8:1, 9:1}
for r,sc in seeds.items():
    for c in range(sc+1,5):
        out[r][c] = 2
    out[r][sc] = 4
for row in out: print(row)

out2 = [row[:] for row in out]
for r in range(4):
    out2[r][5] = 2   # mirror lines reach the other bar's column
for row in out2: print(row)

